css:
.loader { display: flex; flex-direction: column; gap: calc(var(--loader-size) * .05); width: var(--loader-size); }
.loader .tabs { display: flex; gap: calc(var(--loader-size) * .07); }
.loader .tabs i { flex: 1; height: calc(var(--loader-size) * .07); border-radius: 9999px; background: color-mix(in srgb, var(--loader-color) 25%, transparent); }
.loader .bar { width: 30%; height: calc(var(--loader-size) * .035); border-radius: 9999px; background: var(--loader-color); animation: twTabSlide calc(var(--loader-speed) * 2.4) cubic-bezier(.4, 0, .2, 1) infinite; }
@keyframes twTabSlide { 0%, 10% { transform: translateX(0); } 40%, 50% { transform: translateX(118%); } 80%, 90% { transform: translateX(236%); } 100% { transform: translateX(0); } }
